Rules.InvariantScript:
UpdateContext(
    {
        var_visibleDetalhes: false,
        var_mapSelect: ""
    }
);
ClearCollect(
    col_dadosCCI,
    AddColumns(
        Filter(
            SortByColumns(
                'tbl_CHECK-LIST-ALL-ITENS',
                "ID",
                SortOrder.Descending
            ),
            Modulo = "Check-list CCI" And Status.Value = "Em Atendimento"
        ),
        VEICULO,
        LookUp(
            'tbl_CHECK-LIST-VEICULO-CCI',
            ID_FORMS = ID_CheckList,
            'IDENTIFICAÇÃO DO VEÍCULO'
        )
    )
);
ClearCollect(
    col_painelOperacionalVeiculos,
    tbl_gestaoVeiculosRea
);
ForAll(
    col_painelOperacionalVeiculos As COL_VEICULOS,
    Patch(
        col_painelOperacionalVeiculos,
        COL_VEICULOS,
        {
            status: If(
                CountRows(
                    Filter(
                        col_dadosCCI,
                        VEICULO = COL_VEICULOS.identificacao
                    )
                ) > 0 And IsBlank(
                    First(
                        Filter(
                            tbl_ReaOcorrencias,
                            Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = COL_VEICULOS.identificacao
                        )
                    ).Veiculo_identificacao
                ),
                "Média",
                If(
                    !IsBlank(
                        First(
                            Filter(
                                tbl_ReaOcorrencias,
                                Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = COL_VEICULOS.identificacao
                            )
                        ).Veiculo_identificacao
                    ),
                    "Crítico",
                    "Operacional"
                )
            )
        }
    )
)

UpdateContext(
    {
        var_visibleDetalhes: false,
        var_mapSelect: ""
    }
);
ClearCollect(
    col_dadosCCI,
    AddColumns(
        Filter(
            'tbl_CHECK-LIST-ALL-ITENS',
            Modulo = "Check-list CCI" And Status.Value = "Em Atendimento"
        ),
        VEICULO,
        LookUp(
            'tbl_CHECK-LIST-VEICULO-CCI',
            ID_FORMS = ID_CheckList,
            'IDENTIFICAÇÃO DO VEÍCULO'
        )
    )
);
ForAll(
    col_painelOperacionalVeiculos As COL_VEICULOS,
    Patch(
        col_painelOperacionalVeiculos,
        COL_VEICULOS,
        {
            status: If(
                CountRows(
                    Filter(
                        col_dadosCCI,
                        VEICULO = COL_VEICULOS.identificacao
                    )
                ) > 0 And IsBlank(
                    First(
                        Filter(
                            tbl_ReaOcorrencias,
                            Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = COL_VEICULOS.identificacao
                        )
                    ).Veiculo_identificacao
                ),
                "Média",
                If(
                    !IsBlank(
                        First(
                            Filter(
                                tbl_ReaOcorrencias,
                                Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = COL_VEICULOS.identificacao
                            )
                        ).Veiculo_identificacao
                    ),
                    "Crítico",
                    "Operacional"
                )
            )
        }
    )
)

UpdateContext(
    {
        var_visibleDetalhes: true,
        var_itensDetalhes: Filter(
            col_dadosCCI,
            VEICULO = ThisItem.identificacao
        ),
        var_baixaCCI: First(
            Filter(
                tbl_ReaOcorrencias,
                Tipo_ocorrencia.Value = "Baixa do CCI" And Status.Value = "Aberto" And Veiculo_identificacao = ThisItem.identificacao
            )
        ),
        var_cciNome: ThisItem.identificacao
    }
)

RGBA(
    139,
    154,
    159,
    1
)
